import json,pathlib
rows=[]
def add(date,code,year,title,summary,source_title,url,evidence):
 rows.append(dict(date=date,code=code,year=year,title=title,summary=summary,source_title=source_title,url=url,evidence=evidence,confidence='high'))
add('04-01','GBR',1918,'Création de la Royal Air Force','Le Royaume-Uni réunit ses services aériens militaire et naval dans la Royal Air Force, pendant la Première Guerre mondiale.','Royal Air Force — Our history','https://www.raf.mod.uk/what-we-do/our-history/','La RAF indique sa formation le 1 April 1918.')
add('04-02','ARG',1982,'Début de la guerre des Malouines','Les forces argentines débarquent dans les îles Malouines/Falkland, administrées par le Royaume-Uni. Cette occupation déclenche la guerre entre les deux pays.','Royal Air Force — Falklands conflict','https://www.raf.mod.uk/news/articles/royal-air-force-remembers-start-of-falklands-conflict/','Le texte date explicitement l’invasion argentine du 2 April 1982.')
add('04-03','USA',1948,'Promulgation du plan Marshall','Harry Truman signe la loi de coopération économique qui met en œuvre le plan Marshall, consacré au redressement de l’Europe après la guerre.','National Archives — Marshall Plan','https://www.archives.gov/milestone-documents/marshall-plan','Signature de l’Economic Cooperation Act par Truman le April 3, 1948.')
add('04-04','SEN',1960,'Accords préparant l’indépendance','La France, le Sénégal, la République soudanaise et la Fédération du Mali signent ou paraphent les accords préparant le transfert de souveraineté. Il ne faut pas confondre cette signature avec son entrée en vigueur ultérieure.','Bibliothèque nationale de France — Accords du 4 avril 1960','https://catalogue.bnf.fr/ark%3A/12148/cb331952504','Le titre du document original donne les parties et la date du 4 avril 1960.')
